def _normpath(self, pathname):
        "Return path normalized for duscan usage: no trailing slash."
        if pathname == '/':
            pathname = ''
        elif pathname.endswith('/'):
            pathname = pathname[:-1]
        assert not pathname.endswith('/'), pathname
        return pathname

